const c = $input.first().json;
if (!c || c.enabled !== true || !c.settings) { return []; }
const s = c.settings;

// Lista vazia = a automacao nao roda sozinha.
const dias = Array.isArray(s.run_days_of_week) ? s.run_days_of_week : [];
if (dias.length === 0) { return []; }

// Dia e hora em Brasilia, independente do fuso do servidor n8n.
const fmt = new Intl.DateTimeFormat('en-US', {
  timeZone: 'America/Sao_Paulo',
  weekday: 'short',
  hour: 'numeric',
  hourCycle: 'h23'
});
const partes = {};
fmt.formatToParts(new Date()).forEach(function (p) { partes[p.type] = p.value; });
const MAPA_DIA = { Sun: 0, Mon: 1, Tue: 2, Wed: 3, Thu: 4, Fri: 5, Sat: 6 };
const hoje = MAPA_DIA[partes.weekday];
const hora = parseInt(partes.hour, 10);

if (dias.indexOf(hoje) === -1) { return []; }

// Hora EXATA, e nao `hora < run_hour`.
//
// O gatilho acorda de hora em hora, entao este no e o unico dono da decisao:
// com `>=`, uma vez passada a hora configurada ele deixaria passar TODAS as
// chamadas seguintes do dia e a automacao escreveria um artigo por hora ate a
// meia-noite. Com igualdade, so a visita das HH:05 da hora marcada passa.
//
// O preco e que um n8n fora do ar naquela hora especifica perde o dia. E o
// lado certo para errar: perder um artigo custa um dia de atraso, gerar quinze
// custa a fila de revisao inteira.
if (hora !== s.run_hour) { return []; }

const hist = (c.historico_recente || []).map(function (p) { return '- ' + p.title; }).join('\n');
return [{ json: {
  settings: s,
  categories: c.categories || [],
  authors: c.authors || [],
  historico_titulos: hist,
  topicos_recentes: (c.topics_recentes || []).join(', '),
  temas_desejados: (s.topics || []).join(', ')
} }];

// O escritor devolve markdown puro, com as fontes DEPOIS de um delimitador.
// O blog nao publica secao de fontes, entao elas saem do corpo e vao so para
// o ai_metadata, onde quem aprova consegue conferir.

const bruto = String($input.first().json.output || '').trim();
if (!bruto) { throw new Error('O escritor devolveu texto vazio.'); }

const txt = bruto.replace(/^```[a-z]*\s*/i, '').replace(/```\s*$/, '').trim();

const mTags = txt.match(/^TAGS:\s*(.+)$/im);
const slug = (s) => s.trim().toLowerCase()
  .normalize('NFD').replace(/[̀-ͯ]/g, '')
  .replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
const tag_slugs = mTags
  ? mTags[1].split(',').map(slug).filter(Boolean).slice(0, 6)
  : [];

const semTags = txt.replace(/^TAGS:.*$/im, '').trim();

const partes = semTags.split(/^\s*-{3,}\s*FONTES\s*-{3,}\s*$/im);
const corpo = partes[0].trim();
const blocoFontes = partes.length > 1 ? partes[1] : '';

// Rede de seguranca: se o modelo publicou a secao de fontes dentro do artigo
// mesmo tendo sido instruido a nao fazer, remove do corpo.
const corpoLimpo = corpo.split(/^##\s*Fontes e Refer[eê]ncias\s*$/im)[0].trim();

const mTitulo = corpoLimpo.match(/^#\s+(.+)$/m);
const titulo = mTitulo ? mTitulo[1].trim() : '';
if (!titulo) { throw new Error('Nao encontrei o titulo (linha iniciando com # ).'); }

// Aceita barra vertical (formato atual) ou traco (formato antigo) como separador.
const fontes = [];
let atual = null;
for (const linha of blocoFontes.split('\n')) {
  const m = linha.match(/^\s*[-*]\s*\*\*(.+?)\*\*\s*[|–—-]?\s*(.*)$/);
  if (m) {
    atual = { titulo: m[1].trim(), fonte_instituicao: (m[2] || '').trim(), url: '' };
    fontes.push(atual);
    continue;
  }
  const u = linha.match(/(https?:\/\/[^\s)\]]+)/);
  if (u && atual && !atual.url) { atual.url = u[1]; }
}
const fontesValidas = fontes.filter((f) => f.url);

const palavras = corpoLimpo.split(/\s+/).filter(Boolean).length;
const secoes = (corpoLimpo.match(/^##\s+/gm) || []).length;

let resumo = '';
for (const bloco of corpoLimpo.split(/\n\s*\n/)) {
  const b = bloco.trim();
  if (!b || b.startsWith('#') || b.startsWith('-') || b.startsWith('>')) { continue; }
  resumo = b.replace(/[*_`]/g, '');
  break;
}
if (resumo.length > 400) { resumo = resumo.slice(0, 397) + '...'; }

// Marcas de texto de IA que o usuario pediu para eliminar. Nao reescrevemos o
// texto: avisamos quem revisa, que decide publicar, editar ou descartar.
const avisos = [];
if (fontesValidas.length === 0) { avisos.push('Nenhuma fonte com URL foi declarada.'); }
if (secoes < 9) { avisos.push('Apenas ' + secoes + ' secoes H2; o padrao e de 9 a 13.'); }
if (palavras > 2300) { avisos.push(palavras + ' palavras; o teto e 2300.'); }
if (!/^##\s*FAQ/im.test(corpoLimpo)) { avisos.push('O artigo nao tem secao de FAQ.'); }

const travessoes = (corpoLimpo.match(/[—–]/g) || []).length;
if (travessoes > 0) { avisos.push(travessoes + ' travessao(oes) no texto; era para nao haver nenhum.'); }

if (/^##\s*(Conclus|Reflex|Consideraç|Consideracoes|Próximo passo|Proximo passo)/im.test(corpoLimpo)) {
  avisos.push('Titulo de secao generico (Conclusao/Reflexao) que deveria ter sido evitado.');
}
const cliches = ['não é apenas', 'não se trata apenas', 'mais do que nunca', 'em um mundo cada vez mais', 'no cenário atual', 'é importante destacar', 'vale ressaltar', 'em suma', 'o futuro pertence', 'alavancar'];
const achados = cliches.filter((c) => corpoLimpo.toLowerCase().indexOf(c) !== -1);
if (achados.length) { avisos.push('Construcoes de IA encontradas: ' + achados.join('; ') + '.'); }

return [{ json: {
  titulo,
  artigo_markdown: corpoLimpo,
  resumo_executivo: resumo,
  fontes: fontesValidas,
  palavras,
  secoes,
  tag_slugs,
  avisos: avisos.length ? avisos : null
} }];

// O Unsplash indexa em ingles, entao a busca sai das tags e de um mapa de
// termos do setor. Query curta acha foto melhor do que frase longa.
const j = $input.first().json;

const MAPA = {
  fidelizacao: 'customer loyalty',
  loyalty: 'customer loyalty',
  coalizao: 'business partnership',
  pontos: 'reward points',
  milhas: 'airline travel',
  gamificacao: 'game design',
  engajamento: 'customer engagement',
  retencao: 'customer retention',
  churn: 'business analytics',
  crm: 'customer data',
  varejo: 'retail store',
  ecommerce: 'online shopping',
  dados: 'data analytics',
  ia: 'artificial intelligence',
  marca: 'brand strategy',
  cliente: 'customer service',
  mercado: 'business meeting',
  estrategia: 'business strategy'
};

const tags = Array.isArray(j.tag_slugs) ? j.tag_slugs : [];
const termos = [];
for (const t of tags) {
  const chave = String(t).toLowerCase();
  for (const k of Object.keys(MAPA)) {
    if (chave.indexOf(k) !== -1 && termos.indexOf(MAPA[k]) === -1) {
      termos.push(MAPA[k]);
    }
  }
}

// Sem correspondencia, cai num termo neutro e corporativo em vez de arriscar
// uma busca literal em portugues, que costuma devolver foto fora de contexto.
if (termos.length === 0) { termos.push('business strategy meeting'); }

return [{ json: { query: termos.slice(0, 2).join(' ') } }];

// Este n8n guarda binario em modo separado: item.binary.data.data e uma
// referencia, nao o conteudo. getBinaryDataBuffer traz os bytes de verdade.
const meta = $input.first().binary && $input.first().binary.data;
if (!meta) { return [{ json: { capa_ok: false, motivo: 'Nenhum binario recebido.' } }]; }

const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
if (!buf || !buf.length) { return [{ json: { capa_ok: false, motivo: 'Binario vazio.' } }]; }

const MIMES = ['image/png', 'image/jpeg', 'image/webp'];
const mime = MIMES.indexOf(meta.mimeType) !== -1 ? meta.mimeType : 'image/jpeg';

// A edge function recusa acima de 5 MB; melhor descobrir aqui do que levar 400.
if (buf.length > 5 * 1024 * 1024) {
  return [{ json: { capa_ok: false, motivo: 'Imagem de ' + Math.round(buf.length / 1024) + ' kB, acima do limite de 5 MB.' } }];
}

return [{ json: {
  capa_ok: true,
  banner_image_base64: buf.toString('base64'),
  banner_image_mime: mime,
  tamanho_kb: Math.round(buf.length / 1024)
} }];
